package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;import java.time.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class ProviderCallNativeMySqlTest {
 WorkerNativeSnapshotMySqlTest f;JdbcProviderCallTelemetry reader;
 @BeforeEach void setup()throws Exception{f=new WorkerNativeSnapshotMySqlTest();f.setup();reader=new JdbcProviderCallTelemetry(f.f.db.source,f.f.h.newsFlow.day.manager,f.f.clock);}
 @AfterEach void restore(){f.restore();}
 @Test void completeActualMysqlProofPreservesUnknownAgeAndNoRefund(){var initial=reader.read();assertNotNull(initial);assertEquals(0,initial.unknownCalls());var store=new UnknownCallJdbcStore(f.state,f.rows,new JdbcJobRecords(f.f.db.source),"fictional-native-provider-monitor",e->true);new UnknownCallRecoveryService(f.f.db.writes,store,f.f.clock).release(f.state.slot().attempt(),UnknownCallRecoveryService.Cause.STOPPED_PROCESS,new SharedWriteExecutor.ActionContext("fictional-native-provider-unknown",f.state.slot().attempt(),null));var value=new JdbcProviderCallTelemetry(f.f.db.source,f.f.h.newsFlow.day.manager,Clock.fixed(f.now.plusSeconds(10),ZoneOffset.UTC)).read();assertNotNull(value);assertEquals(1,value.unknownCalls());assertEquals(10,value.oldestUnknownSeconds());assertEquals(0,value.configurationBlockedRoots());assertEquals(2,f.f.h.newsFlow.sends);assertEquals(1,new JdbcJobRecords(f.f.db.source).byId(f.f.prepared.input().ownerId()).callCount());}
 @Test void actualNativeConfigurationFailureAndCorruptedClaimAreNotHealthy(){var claim=f.f.worker.claim(new SharedWriteExecutor.ActionContext("fictional-native-snapshot-claim",f.f.prepared.input().ownerId(),f.f.prepared.input().inputHash()));var id=claim.permit().identity();assertNotNull(id);assertEquals(WorkerAuthorizationService.State.SENT,f.f.worker.dispatch(claim.permit(),request->"fictional-provider-configuration-failure").state());var owner=f.rows.attempt(id.attemptId()).owner();new AttemptFailureService(f.f.db.writes,new JdbcAttemptFailure(f.f.db.source),f.f.clock,owner).fail(id,AttemptFailureService.Failure.CONFIGURATION,null,new SharedWriteExecutor.ActionContext("fictional-native-provider-block",id.attemptId(),null));var value=reader.read();assertNotNull(value);assertEquals(1,value.configurationBlockedRoots());f.f.db.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='worker_claim' AND JSON_UNQUOTE(JSON_EXTRACT(target_key_json,'$.attempt_id'))=?",new byte[32],id.attemptId());assertNull(reader.read());assertEquals(2,f.f.h.newsFlow.sends);}
}
